insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('628c4850-114a-46d2-a08f-6d55d6218677', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', null, 'topic'::public.curated_course_node_type, 'Material Thinking and Construction Logic', 'This opening section establishes construction as a design discipline. Students learn that buildings are not just represented; they are assembled from materials, labor, systems, tolerances, codes, supply chains, and maintenance realities.', 0),
  ('1139cf36-342f-4b7f-9905-8c7666745c4a', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '628c4850-114a-46d2-a08f-6d55d6218677', 'subtopic'::public.curated_course_node_type, 'From Design Intent to Built Form', 'The point is to connect architectural ideas to physical decisions that survive procurement, construction, use, and weather.', 0),
  ('95bcd09f-c7c5-408e-b0ec-ddbdd9750e31', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '1139cf36-342f-4b7f-9905-8c7666745c4a', 'concept'::public.curated_course_node_type, 'Design intent, performance criteria, and detail strategy', null, 0),
  ('e80fa298-c875-4dba-8231-9b9e272a8d5f', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '1139cf36-342f-4b7f-9905-8c7666745c4a', 'concept'::public.curated_course_node_type, 'Material, assembly, system, and building scales', null, 1),
  ('d9fe4c0b-9101-4a5f-948c-6d7fa0d1f54d', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '1139cf36-342f-4b7f-9905-8c7666745c4a', 'concept'::public.curated_course_node_type, 'Precedents, standards, and field conditions', null, 2),
  ('af5b5905-b0b7-4867-be76-e5b25c9a72b5', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '1139cf36-342f-4b7f-9905-8c7666745c4a', 'concept'::public.curated_course_node_type, 'Trade-offs between expression, cost, performance, and risk', null, 3),
  ('bb7ce2cc-3344-4f55-8f2a-66a827b1e929', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '628c4850-114a-46d2-a08f-6d55d6218677', 'subtopic'::public.curated_course_node_type, 'Assembly Thinking', 'Students learn to see walls, roofs, floors, and openings as layered systems with jobs to do.', 1),
  ('1c661e0a-cdad-4919-b299-bc0ff38202b0', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', 'bb7ce2cc-3344-4f55-8f2a-66a827b1e929', 'concept'::public.curated_course_node_type, 'Structure, enclosure, control layers, finishes, and services', null, 0),
  ('9bcac307-de1d-47f5-bbf5-a1c55877cbe5', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', 'bb7ce2cc-3344-4f55-8f2a-66a827b1e929', 'concept'::public.curated_course_node_type, 'Load path, drainage path, air path, and thermal path', null, 1),
  ('dab202c2-4ff6-48b1-bf33-dcde8e4c785a', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', 'bb7ce2cc-3344-4f55-8f2a-66a827b1e929', 'concept'::public.curated_course_node_type, 'Interfaces and transitions', null, 2),
  ('902f70c4-5dff-4810-aedc-51654d81236e', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', 'bb7ce2cc-3344-4f55-8f2a-66a827b1e929', 'concept'::public.curated_course_node_type, 'Maintenance, repair, and replacement thinking', null, 3),
  ('4d431a8c-3e1f-4a74-932f-cab35c7641fe', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '628c4850-114a-46d2-a08f-6d55d6218677', 'subtopic'::public.curated_course_node_type, 'Construction Culture and Responsibility', 'This subtopic introduces the people, contracts, labor, and ethical responsibilities behind material decisions.', 2),
  ('cd2b34c6-d928-420a-8eed-0b4043d58382', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '4d431a8c-3e1f-4a74-932f-cab35c7641fe', 'concept'::public.curated_course_node_type, 'Architect, contractor, consultant, fabricator, and trades roles', null, 0),
  ('f89d1ea4-aee6-40e8-a811-a334fe678fbc', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '4d431a8c-3e1f-4a74-932f-cab35c7641fe', 'concept'::public.curated_course_node_type, 'Shop drawings, RFIs, submittals, and field review', null, 1),
  ('716d99c2-896c-44d5-bca7-e12bcb7f913a', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '4d431a8c-3e1f-4a74-932f-cab35c7641fe', 'concept'::public.curated_course_node_type, 'Safety, waste, and environmental responsibility', null, 2),
  ('9d32e4c8-12c8-40e5-94b7-ca4e840c93d3', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '4d431a8c-3e1f-4a74-932f-cab35c7641fe', 'concept'::public.curated_course_node_type, 'Respect for craft and construction labor', null, 3),
  ('68315322-cd24-430a-afb9-1499f3d9de3c', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', null, 'topic'::public.curated_course_node_type, 'Material Properties, Testing, and Selection', 'This unit gives students the vocabulary to select materials intelligently. The point is to move beyond appearance into measurable behavior, risks, and life-cycle consequences.', 1),
  ('1cef56df-d0a1-4503-a08d-bf93aa0e48a9', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '68315322-cd24-430a-afb9-1499f3d9de3c', 'subtopic'::public.curated_course_node_type, 'Physical and Mechanical Properties', 'Students learn properties that determine whether a material can carry load, resist damage, and meet design intent.', 0),
  ('81ab27fb-a3b1-43de-b5af-b0e35322cef5', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '1cef56df-d0a1-4503-a08d-bf93aa0e48a9', 'concept'::public.curated_course_node_type, 'Density, strength, stiffness, ductility, hardness, and creep', null, 0),
  ('7b47cb28-35a6-4a6f-a16a-8b99994d6521', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '1cef56df-d0a1-4503-a08d-bf93aa0e48a9', 'concept'::public.curated_course_node_type, 'Thermal expansion, conductivity, and dimensional stability', null, 1),
  ('4e7d9bc9-36cd-4d1d-82ce-4afc44a08460', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '1cef56df-d0a1-4503-a08d-bf93aa0e48a9', 'concept'::public.curated_course_node_type, 'Porosity, absorption, permeability, and capillarity', null, 2),
  ('819b176c-a0b0-49b7-8658-5b029b77c54a', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '1cef56df-d0a1-4503-a08d-bf93aa0e48a9', 'concept'::public.curated_course_node_type, 'Acoustic, optical, and tactile properties', null, 3),
  ('d14b353e-754e-41af-bdc6-538da1aff652', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '68315322-cd24-430a-afb9-1499f3d9de3c', 'subtopic'::public.curated_course_node_type, 'Durability, Fire, Moisture, and Weathering', 'Materials age, burn, corrode, rot, crack, stain, and fail differently; students learn to anticipate those paths.', 1),
  ('e876f0f0-fe76-4609-bcbb-6c6928bf8c5c', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', 'd14b353e-754e-41af-bdc6-538da1aff652', 'concept'::public.curated_course_node_type, 'Freeze-thaw, UV exposure, corrosion, decay, and abrasion', null, 0),
  ('3e1bebb4-9cbb-47f6-b870-0ecb2e644afd', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', 'd14b353e-754e-41af-bdc6-538da1aff652', 'concept'::public.curated_course_node_type, 'Fire resistance, combustibility, and smoke contribution', null, 1),
  ('263b0678-c96a-4e0e-bc08-84d11a3d6f18', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', 'd14b353e-754e-41af-bdc6-538da1aff652', 'concept'::public.curated_course_node_type, 'Moisture storage, drying potential, and mold risk', null, 2),
  ('28ae00a9-f4a3-40d5-8953-9d2cd7849489', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', 'd14b353e-754e-41af-bdc6-538da1aff652', 'concept'::public.curated_course_node_type, 'Maintenance cycles and service life', null, 3),
  ('9529908c-8c74-4a42-a060-8a9248036101', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '68315322-cd24-430a-afb9-1499f3d9de3c', 'subtopic'::public.curated_course_node_type, 'Selection Criteria and Testing', 'Students practice comparing materials using evidence rather than preference alone.', 2),
  ('1d6fb6b0-9827-4a9d-9fdc-9229922c8997', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '9529908c-8c74-4a42-a060-8a9248036101', 'concept'::public.curated_course_node_type, 'Standards, mockups, certifications, and test reports', null, 0),
  ('9f67edd7-911b-4825-b91f-742eed5cf6c8', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '9529908c-8c74-4a42-a060-8a9248036101', 'concept'::public.curated_course_node_type, 'Cost, availability, lead time, and local skill', null, 1),
  ('7f9ee81e-b4cb-4936-8e4b-2143440dc477', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '9529908c-8c74-4a42-a060-8a9248036101', 'concept'::public.curated_course_node_type, 'Embodied carbon, toxicity, and responsible sourcing', null, 2),
  ('069244ef-b0d0-4e3f-a600-a83feb9bd8d1', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '9529908c-8c74-4a42-a060-8a9248036101', 'concept'::public.curated_course_node_type, 'Fitness for climate, code, occupancy, and use', null, 3),
  ('e630e2b3-7a7c-43bd-a45d-a21cee070668', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', null, 'topic'::public.curated_course_node_type, 'Wood and Timber Construction', 'Wood is renewable, workable, expressive, and vulnerable. This section covers wood as structure, envelope, finish, and carbon strategy.', 2),
  ('3a78ffb5-241b-4222-9916-efa411023c7f', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', 'e630e2b3-7a7c-43bd-a45d-a21cee070668', 'subtopic'::public.curated_course_node_type, 'Light Wood Framing', 'Students learn platform framing as a coordinated system of studs, joists, sheathing, openings, fasteners, and bracing.', 0),
  ('074c30ac-d396-4577-bc5b-683adc44746c', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '3a78ffb5-241b-4222-9916-efa411023c7f', 'concept'::public.curated_course_node_type, 'Stud spacing, plates, headers, joists, rafters, and trusses', null, 0),
  ('c2c9e53e-f0f3-4f89-b91f-b05e72d44277', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '3a78ffb5-241b-4222-9916-efa411023c7f', 'concept'::public.curated_course_node_type, 'Shear walls, diaphragms, and lateral load paths', null, 1),
  ('ad531589-ffe8-4dbf-8d26-f5122c87680f', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '3a78ffb5-241b-4222-9916-efa411023c7f', 'concept'::public.curated_course_node_type, 'Openings, hold-downs, and connection logic', null, 2),
  ('4a8ebca0-fb18-42b2-9543-8539bd8fa25c', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '3a78ffb5-241b-4222-9916-efa411023c7f', 'concept'::public.curated_course_node_type, 'Fire blocking, acoustic separation, and services', null, 3),
  ('b8a89ffe-ec9f-4d74-b628-cbcf62e141de', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', 'e630e2b3-7a7c-43bd-a45d-a21cee070668', 'subtopic'::public.curated_course_node_type, 'Mass Timber and Engineered Wood', 'This subtopic introduces contemporary timber systems that expand span, height, precision, and prefabrication.', 1),
  ('9ed66727-284b-4b78-9a5f-f54f6fe13dd8', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', 'b8a89ffe-ec9f-4d74-b628-cbcf62e141de', 'concept'::public.curated_course_node_type, 'Glulam, CLT, LVL, PSL, and nail-laminated timber', null, 0);
