  ('27e2627a-8ac2-4b49-9c95-90f5dda74099', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', null, 'topic'::public.curated_course_node_type, 'Steel and Metals', 'This unit covers metals as structural frames, cladding, roofing, fasteners, finishes, and precision components. Students learn how metal performance depends on alloy, shape, connection, protection, and fabrication.', 3),
