  ('86e6b921-2996-4758-b06f-d75940da8337', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', null, 'topic'::public.curated_course_node_type, 'Concrete and Cementitious Systems', 'Concrete is structural, plastic, massive, durable, carbon-intensive, and deeply tied to formwork and sequencing. Students learn concrete as chemistry, construction process, and architectural material.', 4),
