  ('74a3e2f9-ef16-4f82-81a2-bd64b5b50870', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '64ed61f0-60ae-4232-ac68-6a1d5605cec5', 'concept'::public.curated_course_node_type, 'Cement, aggregates, water, admixtures, and supplementary cementitious materials', null, 0),
  ('b849eae8-091c-4650-a3cc-086b4add4bf7', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '64ed61f0-60ae-4232-ac68-6a1d5605cec5', 'concept'::public.curated_course_node_type, 'Water-cement ratio, curing, shrinkage, and cracking', null, 1),
  ('bfecee78-7604-4a58-8ad1-714d385abb3a', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '64ed61f0-60ae-4232-ac68-6a1d5605cec5', 'concept'::public.curated_course_node_type, 'Compressive strength, reinforcement, and cover', null, 2),
  ('f763595e-a36b-432d-850a-c6456d6de2df', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '64ed61f0-60ae-4232-ac68-6a1d5605cec5', 'concept'::public.curated_course_node_type, 'Low-carbon mixes and performance specifications', null, 3),
