  ('1bf02138-005d-451f-8f5b-ad3da2a0b3c4', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', 'c5b9f346-03b4-4611-af10-4e427b66c473', 'concept'::public.curated_course_node_type, 'Cast-in-place, precast, tilt-up, and shotcrete', null, 0),
