  ('7126ee6d-58ff-414a-8eb2-a8c4e9fb5d51', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', 'c5b9f346-03b4-4611-af10-4e427b66c473', 'concept'::public.curated_course_node_type, 'Placement, vibration, curing, and inspection', null, 3),
  ('7c1b2aec-5de5-4634-a4f6-6c9854b6ff52', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '86e6b921-2996-4758-b06f-d75940da8337', 'subtopic'::public.curated_course_node_type, 'Durability, Repair, and Expression', 'Students learn how concrete ages and how architects can design for longevity.', 2),
