  ('fa186c68-2aed-49c3-a107-2165de6658ee', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '7c1b2aec-5de5-4634-a4f6-6c9854b6ff52', 'concept'::public.curated_course_node_type, 'Repair, patching, protection, and adaptive reuse', null, 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
