  ('9e25625d-b070-490c-8125-f4ac7ebcddd5', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', null, 'topic'::public.curated_course_node_type, 'Masonry and Unit Construction', 'Masonry teaches modular thinking, craft, compression, water management, and material memory. This section covers unit systems from brick and block to stone and veneer.', 5),
