  ('b5232fd3-7c8e-46d4-b84a-c462ae130640', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', null, 'topic'::public.curated_course_node_type, 'Glass, Glazing, and Curtain Walls', 'Glass is both technical system and cultural symbol. Students learn its optical, thermal, structural, safety, and assembly consequences.', 6),
  ('3578f48b-7f6b-488e-ad7e-198d46ac3ecd', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', 'b5232fd3-7c8e-46d4-b84a-c462ae130640', 'subtopic'::public.curated_course_node_type, 'Glass Properties and Glazing Types', 'Students compare glass products by strength, safety, energy, daylight, and appearance.', 0),
