  ('0e84c24f-2782-4a35-a93a-866a0b5e464c', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '3578f48b-7f6b-488e-ad7e-198d46ac3ecd', 'concept'::public.curated_course_node_type, 'Low-e coatings, frit, tint, and bird-safe treatments', null, 1),
  ('04c53826-1071-4e4f-9ef1-f1d775ad3a85', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '3578f48b-7f6b-488e-ad7e-198d46ac3ecd', 'concept'::public.curated_course_node_type, 'U-value, SHGC, visible transmittance, and glare', null, 2),
  ('65907a50-0131-4a51-b321-e809dbb25091', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '3578f48b-7f6b-488e-ad7e-198d46ac3ecd', 'concept'::public.curated_course_node_type, 'Acoustics, safety, and impact criteria', null, 3),
  ('3482ce6c-5e86-4568-a700-e399bd076b92', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', 'b5232fd3-7c8e-46d4-b84a-c462ae130640', 'subtopic'::public.curated_course_node_type, 'Curtain Wall and Storefront Systems', 'This subtopic explains how transparent facades are framed, drained, anchored, and coordinated.', 1),
  ('a3b30e0d-d68e-489c-81eb-6ba72ebe624c', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '3482ce6c-5e86-4568-a700-e399bd076b92', 'concept'::public.curated_course_node_type, 'Stick-built, unitized, structural glazing, and point-supported systems', null, 0),
  ('60e84074-8d72-41bd-8e35-b4f4de865743', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '3482ce6c-5e86-4568-a700-e399bd076b92', 'concept'::public.curated_course_node_type, 'Mullions, anchors, pressure plates, gaskets, and sealants', null, 1),
  ('34933e75-c533-4a1b-af6d-8f67d25b44ab', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '3482ce6c-5e86-4568-a700-e399bd076b92', 'concept'::public.curated_course_node_type, 'Thermal breaks, condensation, and perimeter fire safing', null, 2),
