  ('a0c3d47b-0619-4c12-822f-2a1cd2da7b57', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '8763cf48-70ca-4a2e-bf8b-3f5de0663248', 'concept'::public.curated_course_node_type, 'Water penetration and air leakage', null, 1),
  ('ade4eee2-4c82-4ad2-bfe3-399d38bcca9c', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '8763cf48-70ca-4a2e-bf8b-3f5de0663248', 'concept'::public.curated_course_node_type, 'Cleaning, replacement, and access', null, 2),
