  ('c8e7592d-7092-4a9c-81fd-1bc91f2ca465', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', null, 'topic'::public.curated_course_node_type, 'Building Envelope Science: Heat, Air, and Moisture', 'This unit gives students the building science needed to understand envelope performance. The point is practical: prevent leaks, condensation, mold, energy waste, and premature failure.', 7),
  ('52f440b6-5977-44d9-8fcb-7c795522a873', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', 'c8e7592d-7092-4a9c-81fd-1bc91f2ca465', 'subtopic'::public.curated_course_node_type, 'Heat Flow and Thermal Bridging', 'Students learn how heat moves through assemblies and why continuity matters.', 0),
  ('09917238-0230-4149-bfd7-50834ed04b3f', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '52f440b6-5977-44d9-8fcb-7c795522a873', 'concept'::public.curated_course_node_type, 'Conduction, convection, radiation, and thermal mass', null, 0),
  ('05367ffa-e4f4-4afc-b982-c7387ad2f1f5', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '52f440b6-5977-44d9-8fcb-7c795522a873', 'concept'::public.curated_course_node_type, 'R-value, U-factor, and effective assembly performance', null, 1),
  ('cb0cd4d6-133e-4b67-8f66-4787f659638d', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '52f440b6-5977-44d9-8fcb-7c795522a873', 'concept'::public.curated_course_node_type, 'Thermal bridges at slabs, balconies, studs, and frames', null, 2),
  ('b41dafa7-7a87-4df6-ba1d-af02a5962cb3', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '52f440b6-5977-44d9-8fcb-7c795522a873', 'concept'::public.curated_course_node_type, 'Continuous insulation and high-performance enclosure design', null, 3),
  ('0bf0a44f-2e79-4410-bc21-78929f1a0045', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', 'c8e7592d-7092-4a9c-81fd-1bc91f2ca465', 'subtopic'::public.curated_course_node_type, 'Air Leakage and Pressure', 'Air movement carries heat and moisture, so students learn to define and protect air-control layers.', 1),
  ('500b2232-f55f-4958-bb05-0b973b28b41a', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '0bf0a44f-2e79-4410-bc21-78929f1a0045', 'concept'::public.curated_course_node_type, 'Stack effect, wind pressure, and mechanical pressure', null, 0);
