  ('5b17bb08-c895-4d2a-a095-ea96453a5e82', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', null, 'topic'::public.curated_course_node_type, 'Insulation, Air Barriers, Vapor Control, and Weatherproofing', 'This unit focuses on control layers. Students learn to locate, draw, and preserve insulation, air, vapor, water, and weather-resistive barriers across complete assemblies.', 10),
