  ('3562b103-512f-4ad1-8daa-17723b398814', 'f0a1b2c3-4d5e-4a94-9d34-4b5c6d7e8f44', '69d991cd-b08c-49a9-b655-c676f9c8d3b1', 'concept'::public.curated_course_node_type, 'Continuity, hierarchy, redundancy, and access', null, 0),
